package com.euvcraft.lithmod.mc;
import com.google.gson.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;
class T5AssetResourceTest{
 static final Set<String> BLOCKS=Set.of("utility_plant","utility_water_inlet","utility_pure_outlet","pick_and_place","scanner_diagnostic_panel","scanner_water_inlet","scanner_immersion_module","assembly_casing","assembly_power_port");static final Set<String> ITEMS=Set.of("logic_chip_t5","memory_chip_t5","compute_chip_t5","nand_chip_t5","utility_filter","burn_paper","cpu_blank","dimm_blank","microcontroller_blank","resist_t5","immersion_light_source","immersion_optics","immersion_stage","immersion_filtration","immersion_metrology","cpu_t3","cpu_t4","cpu_t5","dimm_t2","dimm_t3","dimm_t4","dimm_t5","microcontroller_t1","microcontroller_t2","microcontroller_t3","microcontroller_t4","microcontroller_t5");
 private static JsonObject json(String p)throws Exception{try(var in=T5AssetResourceTest.class.getResourceAsStream(p)){assertNotNull(in,"Missing "+p);return JsonParser.parseReader(new InputStreamReader(in,StandardCharsets.UTF_8)).getAsJsonObject();}}
 private static void texture(String ref){if(ref.startsWith("lithmod:"))assertNotNull(T5AssetResourceTest.class.getResource("/assets/lithmod/textures/"+ref.substring(8)+".png"),ref);}
 @Test void registeredResourcesHaveRealModelsTexturesNamesAndDrops()throws Exception{var lang=json("/assets/lithmod/lang/en_us.json");for(var id:ITEMS){assertTrue(lang.has("item.lithmod."+id));var model=json("/assets/lithmod/models/item/"+id+".json");texture(model.getAsJsonObject("textures").get("layer0").getAsString());assertEquals("lithmod:item/"+id,json("/assets/lithmod/items/"+id+".json").getAsJsonObject("model").get("model").getAsString());}for(var id:BLOCKS){assertTrue(lang.has("item.lithmod."+id)&&lang.has("block.lithmod."+id));texture(json("/assets/lithmod/models/block/"+id+".json").getAsJsonObject("textures").get("all").getAsString());json("/assets/lithmod/blockstates/"+id+".json");assertEquals("lithmod:"+id,json("/data/lithmod/loot_table/blocks/"+id+".json").getAsJsonArray("pools").get(0).getAsJsonObject().getAsJsonArray("entries").get(0).getAsJsonObject().get("name").getAsString());}}
 @Test void assemblyBootstrapUsesOnlyT1Materials()throws Exception{for(String id:List.of("assembly_casing","assembly_power_port","pick_and_place")){var source=json("/data/lithmod/recipe/crafting/"+id+".json").toString();assertFalse(source.contains("advanced_")||source.matches(".*chip_t[2-8].*"),"T1 bootstrap depends on a later tier: "+id);}}
 @Test void sharedBlanksAndExactSameTierCounts()throws Exception{for(String family:List.of("cpu","dimm","microcontroller")){var blank=family+"_blank";json("/data/lithmod/recipe/crafting/"+blank+".json");int start=family.equals("cpu")?3:family.equals("dimm")?2:1;String chip=family.equals("cpu")?"compute":family.equals("dimm")?"memory":"logic";for(int tier=start;tier<=5;tier++){var r=json("/data/lithmod/machine_recipes/"+family+"_t"+tier+".json");assertEquals("pick_and_place",r.get("machine").getAsString());var ingredients=r.getAsJsonArray("ingredients");assertEquals(2,ingredients.size());assertEquals("lithmod:"+chip+"_chip_t"+tier,ingredients.get(0).getAsJsonObject().get("item").getAsString());assertEquals(family.equals("dimm")?4:1,ingredients.get(0).getAsJsonObject().get("count").getAsInt());assertEquals("lithmod:"+blank,ingredients.get(1).getAsJsonObject().get("item").getAsString());assertEquals(1,ingredients.get(1).getAsJsonObject().get("count").getAsInt());assertEquals("lithmod:"+family+"_t"+tier,r.getAsJsonObject("result").get("item").getAsString());assertEquals(1,r.getAsJsonObject("result").get("count").getAsInt());assertTrue(r.get("ticks").getAsInt()>0);}}}
 @Test void t5UsesEditableCostsAndOnlyApprovedBinningFamilies()throws Exception{var scanner=json("/data/lithmod/machines/lithography_scanner.json");assertTrue(scanner.getAsJsonObject("params").get("pure_water_per_tick_mb").getAsInt()>0);assertTrue(scanner.getAsJsonObject("params").get("diagnostic_min_quality").getAsInt()>0);var plant=json("/data/lithmod/machines/utility_plant.json");assertEquals(plant.getAsJsonObject("params").get("water_per_batch_mb"),plant.getAsJsonObject("params").get("pure_per_batch_mb"));for(String family:List.of("logic","compute")){var r=json("/data/lithmod/high_binning/"+family+"_t4_t5.json");assertEquals(4,r.get("source_tier").getAsInt());assertEquals(5,r.get("target_tier").getAsInt());}assertNull(getClass().getResource("/data/lithmod/high_binning/nand_t4_t5.json"));}
}


